(() => {
  const insertMarkdown = (textarea, markdown) => {
    if (!textarea) return;
    const value = textarea.value || '';
    const prefix = value.endsWith('\n') || value === '' ? '' : '\n';
    textarea.value = value + prefix + markdown + '\n';
    textarea.dispatchEvent(new Event('change', { bubbles: true }));
  };

  const ensureModal = () => {
    if (!window.FileManagerModal) {
      console.warn('[filemanager-md] FileManagerModal not available');
      return null;
    }
    return window.FileManagerModal;
  };

  document.addEventListener('md-mini:insert-image', (event) => {
    const textarea = event.detail ? event.detail.textarea : null;
    const modal = ensureModal();
    if (!textarea || !modal) return;
    modal.open({
      type: 'image',
      filetag: 'forum',
      trigger: 'markdown-image',
      onSelect: (url, meta) => {
        const alt = meta && meta.display_name ? meta.display_name : 'imagem';
        insertMarkdown(textarea, `![${alt}](${url})`);
      },
    });
  });

  document.addEventListener('md-mini:insert-video', (event) => {
    const textarea = event.detail ? event.detail.textarea : null;
    const modal = ensureModal();
    if (!textarea || !modal) return;
    modal.open({
      type: 'video',
      filetag: 'forum',
      trigger: 'markdown-video',
      onSelect: (url) => {
        const html = `<video style="max-width: 100%; width: 100%; height: auto;" controls><source src="${url}" type="video/mp4"></video>`;
        insertMarkdown(textarea, html);
      },
    });
  });

  document.addEventListener('md-mini:insert-audio', (event) => {
    const textarea = event.detail ? event.detail.textarea : null;
    const modal = ensureModal();
    if (!textarea || !modal) return;
    modal.open({
      type: 'audio',
      filetag: 'forum',
      trigger: 'markdown-audio',
      onSelect: (url) => {
        const html = `<audio controls style="width: 100%"><source src="${url}" type="audio/mpeg"></audio>`;
        insertMarkdown(textarea, html);
      },
    });
  });
})();
